   return keys.flatMap(key=>{const [a,b,c]=maps.map(map=>map.get(key));if(!b&&a){if(!equal(a,c))conflicts.push('Segment '+key+' was changed while being removed');return [];}if(!c&&a){if(!equal(a,b))conflicts.push('Segment '+key+' was removed on the backend');return b?[copy(b)]:[];}return [mergeEdits(a,b,c,'segment '+key,conflicts)];});
