 async function openProject(identity){await flush();const result=await request('/dubbing/projects/'+encodeURIComponent(identity));project=copy(result.project||result);baseProject=copy(project);await request('/dubbing/settings',{last_project:project.id});sourcePanel=!project.options?.panels?.left_collapsed;voicePanel=!project.options?.panels?.right_collapsed;dirty=false;conflict=null;selected.clear();page=0;waveform=null;previewMode='original';lastRun=project.latest_run_id||array(project.runs).slice().sort((a,b)=>finite(b.updated)-finite(a.updated))[0]?.id||'';draw();}
