 function jobsHTML(){const jobs=projectJobs().slice(-6);if(!jobs.length)return '<span>No active production stages</span>';return jobs.map(job=>`<button class="dv-job" data-dv-job="${E(job.id)}"><span>${E(titles[job.tool]||job.tool)}</span><span>${E(job.stage||job.message||job.status)}</span>${['running','finalizing'].includes(job.status)?`<progress max="100" ${job.progress_measured===true&&Number.isFinite(job.progress)?`value="${Math.min(99,Math.max(0,job.progress))}"`:''} aria-label="${E(titles[job.tool]||job.tool)} progress"></progress>`:''}</button>`).join('');}
